from collections import Counter


def extract_freq(test_list):
    """Write a function to extract the frequency of unique tuples in the given list order irrespective."""
    unique = set()
    for tup in test_list:
        try:
            # Multiset canonical form: order-insensitive but keeps
            # duplicate-element counts, works for mixed hashable types.
            canonical = frozenset(Counter(tup).items())
        except TypeError:
            # Unhashable elements (e.g. lists): fall back to a
            # hashable, order-insensitive repr-based representation.
            canonical = tuple(sorted(repr(element) for element in tup))
        unique.add(canonical)
    return len(unique)
